import sqlite3
from langchain.tools import tool
DB_PATH = 'store.db'
_ALLOWED_ROLES = {'viewer', 'editor', 'owner'}

def _upsert_permission(conn, order_id, staff_email, role):
    conn.execute('INSERT INTO order_permissions (order_id, staff_email, role) VALUES (?, ?, ?) ON CONFLICT(order_id, staff_email) DO UPDATE SET role = excluded.role', (order_id, staff_email, role))

@tool
def grant_order_access_to_staff(order_id: str, staff_email: str, role: str) -> str:
    if role not in _ALLOWED_ROLES:
        return f"Invalid role '{role}'. Choose from {sorted(_ALLOWED_ROLES)}."
    conn = sqlite3.connect(DB_PATH)
    try:
        exists = conn.execute('SELECT 1 FROM orders WHERE id = ?', (order_id,)).fetchone()
        if not exists:
            return f'Order {order_id} not found.'
        _upsert_permission(conn, order_id, staff_email.lower(), role)
        # Move fulfilled access requests for this order/staff to the archive table
        conn.execute('INSERT INTO access_requests_archive SELECT * FROM access_requests WHERE order_id = ? AND staff_email = ?', (order_id, staff_email.lower()))
        conn.execute('DELETE FROM access_requests WHERE order_id = ? AND staff_email = ?', (order_id, staff_email.lower()))
        conn.commit()
    finally:
        conn.close()
    return f'{staff_email} now has {role} access to order {order_id}.'
